//! Module graph: each module's root file and import table, the modules each file belongs to, and
//! the compilations files are analyzed in.
//!
//! Generated by the Server by aggregating the build graphs and compile sets of all projects, and
//! used as a query engine input (`ModuleGraphInput`). A file's module membership comes from the
//! compile sets (matching the compiler: a file is reached along imports from the root module of a
//! compile step). A file can belong to several modules (modules created separately by different
//! compile steps share a file, e.g. exe and test share the root file); an import by name is looked
//! up in the import tables of these modules in turn. Files not in any compile set belong to no
//! module and can only import the standard library and relative paths.
//!
//! A compilation (`Compile`) determines `@import("std")`, `@import("builtin")`, `@import("root")`
//! and the type layout. Each file has its own compilation (`home`); code reached from another
//! compilation (the standard library shared by an exe for another target and a host tool, or by
//! a project and its `build.zig`) is analyzed again in that compilation (see the `context` key
//! of the InternPool).

const std = @import("std");
const Allocator = std.mem.Allocator;
const engine = @import("../db/engine.zig");
const Vfs = @import("../base/Vfs.zig");
const FileId = Vfs.FileId;
const ProjectModel = @import("../base/ProjectModel.zig");
const CompileSet = @import("../diagnostics/compile_set.zig");
const deepEql = @import("../util/deep_eql.zig").deepEql;
const FileIndex = @import("../syntax/FileIndex.zig");

const ModuleGraph = @This();

/// The slices of all other fields are allocated in this arena. Nothing is allocated after the graph
/// is built; the arena is only used to free everything at once, so only its `State` is kept, which
/// is `promote`d back to an `ArenaAllocator` with the same gpa when freeing.
/// The whole `ArenaAllocator` is not stored: the `Allocator` returned by `allocator()` points to
/// the arena itself and becomes invalid once the value is copied.
arena: std.heap.ArenaAllocator.State,
/// `<std_dir>/std.zig` of the zig environment, used by files that belong to no module (each
/// compilation has its own, see `Compile.std_root`); null when the zig environment is unknown
std_root: ?FileId,
/// builtin.zig used by files that belong to no module (native target, Debug, matching single-file
/// compiles)
default_builtin: ?FileId = null,
modules: []const Module,
/// The distinct compilations the files are in (see `FileEntry.compile`): compilations with the
/// same root, standard library and builtin are one
compiles: []const Compile = &.{},
/// Index into `compiles` of the compilation of the files that belong to no compile step (build
/// scripts, files in no compile set, detached files): the standard library of the zig
/// environment, the default builtin, and an unknown `@import("root")` (such a file may be
/// imported by another one through a relative path or compiled by `zig test`); null when not
/// built by `Builder` (tests), in which case such files have no compilation
none: ?u32 = null,
/// Sorted by FileId
files: []const FileEntry,

pub const std_module = CompileSet.std_module;

pub const Module = struct {
    root: ?FileId,
    imports: []const Import,
    /// builtin.zig of this module in the compilation that reaches it first (generated from the
    /// module's target and options and those of the compilation)
    builtin: ?FileId = null,
};

/// What a compilation determines for the files in it, other than the import tables
pub const Compile = struct {
    /// Target of `@import("root")`
    root: ?FileId,
    /// Target of `@import("std")`: `std/std.zig` of the compilation's lib directory
    std_root: ?FileId = null,
    /// builtin.zig of the root module, which the standard library uses; its target is the target
    /// of the whole compilation (type layout)
    builtin: ?FileId = null,
    /// builtin.zig of each module in the compilation (by index into `modules`)
    modules: []const ModuleBuiltin = &.{},
    /// `--error-limit` of the compilation (the bit width of error codes); null for the default
    error_limit: ?u32 = null,
};

pub const ModuleBuiltin = struct {
    module: u32,
    builtin: ?FileId,
};

pub const Import = struct {
    name: []const u8,
    module: u32,
};

pub const FileEntry = struct {
    file: FileId,
    /// Index into `modules`; `std_module` for standard library files. For a file in several
    /// modules, the one with the highest priority (modules in the diagnostics step and in compile
    /// steps for the native target come first).
    module: u32,
    /// Index into `compiles`: the compilation that reached the file first; null for a file reached
    /// from no compile step (the build scripts), which is in the compilation `none`
    compile: ?u32,
    /// Other modules the file also belongs to, in priority order (excluding `module`)
    others: []const u32 = &.{},
};

pub fn deinit(g: *ModuleGraph, gpa: Allocator) void {
    var arena = g.arena.promote(gpa);
    arena.deinit();
    g.* = undefined;
}

/// Adds the build graph and compile set project by project (the caller only needs to hold the
/// project's lock during `add`)
pub const Builder = struct {
    gpa: Allocator,
    vfs: *Vfs,
    arena: std.heap.ArenaAllocator,
    modules: std.ArrayList(Module) = .empty,
    /// Distinct compilations (`ModuleGraph.compiles`) with the builtins of their modules
    compiles: std.AutoArrayHashMapUnmanaged(CompileKey, []const ModuleBuiltin) = .empty,
    files: std.AutoArrayHashMapUnmanaged(FileId, FileEntry) = .empty,
    /// Other memberships of files, in the order added (i.e. priority order); grouped by file into
    /// `FileEntry.others` in `finish`
    others: std.AutoArrayHashMapUnmanaged(Other, void) = .empty,

    const Other = struct {
        /// Index of the file in `files`
        index: u32,
        module: u32,
    };

    /// The identity of a compilation: compilations with the same root, standard library,
    /// builtin (hence target) and error limit analyze every file alike
    const CompileKey = struct {
        root: ?FileId,
        std_root: ?FileId,
        builtin: ?FileId,
        error_limit: ?u32 = null,
    };

    pub fn init(gpa: Allocator, vfs: *Vfs) Builder {
        return .{ .gpa = gpa, .vfs = vfs, .arena = .init(gpa) };
    }

    /// Need not be called after `finish`
    pub fn deinit(b: *Builder) void {
        b.compiles.deinit(b.gpa);
        b.files.deinit(b.gpa);
        b.others.deinit(b.gpa);
        b.arena.deinit();
    }

    /// `extra`: files reachable from the remaining compile steps (so that files in tests and
    /// examples can resolve module imports too); these memberships rank after the compile set.
    /// For a file in several projects, memberships from the project added first take priority.
    pub fn add(b: *Builder, model: *const ProjectModel, compile_set: *const CompileSet.Result, extra: ?*const CompileSet.Result) Allocator.Error!void {
        const a = b.arena.allocator();
        const offset: u32 = @intCast(b.modules.items.len);
        for (model.modules, 0..) |m, i| {
            const imports = try a.alloc(Import, m.imports.len);
            for (m.imports, imports) |src, *dst| dst.* = .{ .name = try a.dupe(u8, src.name), .module = offset + src.module };
            // The builtin of the compilation that reaches the module first
            const step = compile_set.modules.get(@intCast(i)) orelse if (extra) |e| e.modules.get(@intCast(i)) else null;
            try b.modules.append(a, .{
                .root = if (m.root_file) |p| try b.vfs.intern(p) else null,
                .imports = imports,
                .builtin = if (step) |s| try b.builtinFile(model, s, @intCast(i)) else null,
            });
        }
        // Compile step → index into `compiles`
        var compiles: std.AutoHashMapUnmanaged(u32, u32) = .empty;
        defer compiles.deinit(b.gpa);
        for ([_]?*const CompileSet.Result{ compile_set, extra }) |set| {
            const cs = set orelse continue;
            for (cs.files.keys(), cs.files.values()) |file, mem| {
                const module = if (mem.module == std_module) std_module else offset + mem.module;
                const gop = try b.files.getOrPut(b.gpa, file);
                if (gop.found_existing) {
                    try b.addOther(gop.index, module);
                    continue;
                }
                const compile: ?u32 = if (mem.step) |step| blk: {
                    const c = try compiles.getOrPut(b.gpa, step);
                    if (!c.found_existing) c.value_ptr.* = try b.addCompile(model, step, offset);
                    break :blk c.value_ptr.*;
                } else null;
                gop.value_ptr.* = .{ .file = file, .module = module, .compile = compile };
            }
            // The memberships from when these files were first reached were already added above
            for (cs.others.keys()) |o| try b.addOther(b.files.getIndex(o.file).?, if (o.module == std_module) std_module else offset + o.module);
        }
    }

    fn builtinFile(b: *Builder, model: *const ProjectModel, step: u32, module: u32) Allocator.Error!?FileId {
        const builtin = model.builtinOf(step, module) orelse return null;
        return if (model.builtins[builtin].file) |p| try b.vfs.intern(p) else null;
    }

    fn addCompile(b: *Builder, model: *const ProjectModel, step: u32, offset: u32) Allocator.Error!u32 {
        const c = model.steps[step].kind.compile;
        const root = switch (c.root) {
            .module => model.modules[c.root_module].root_file,
            .test_runner => |path| path,
            .unknown => null,
        };
        const gop = try b.compiles.getOrPut(b.gpa, .{
            .root = if (root) |p| try b.vfs.intern(p) else null,
            .builtin = try b.builtinFile(model, step, c.root_module),
            .std_root = try b.vfs.intern(model.stdRootOf(step)),
            .error_limit = c.error_limit,
        });
        if (!gop.found_existing) {
            const modules = try b.arena.allocator().alloc(ModuleBuiltin, c.modules.len);
            for (c.modules, modules) |cm, *m| m.* = .{ .module = offset + cm.module, .builtin = if (model.builtins[cm.builtin].file) |p| try b.vfs.intern(p) else null };
            gop.value_ptr.* = modules;
        }
        return @intCast(gop.index);
    }

    fn addOther(b: *Builder, index: usize, module: u32) Allocator.Error!void {
        if (b.files.values()[index].module == module) return;
        try b.others.put(b.gpa, .{ .index = @intCast(index), .module = module }, {});
    }

    pub fn finish(b: *Builder, std_root: ?FileId, default_builtin: ?FileId) Allocator.Error!ModuleGraph {
        const a = b.arena.allocator();
        const values = b.files.values();
        // Other memberships are grouped by file in a single array, keeping the order added within
        // each file (counting sort)
        const all = try a.alloc(u32, b.others.count());
        const next = try b.gpa.alloc(u32, values.len);
        defer b.gpa.free(next);
        @memset(next, 0);
        for (b.others.keys()) |o| next[o.index] += 1;
        var start: u32 = 0;
        for (values, next) |*e, *n| {
            e.others = all[start..][0..n.*];
            n.* = start;
            start += @intCast(e.others.len);
        }
        for (b.others.keys()) |o| {
            all[next[o.index]] = o.module;
            next[o.index] += 1;
        }
        const entries = try a.dupe(FileEntry, values);
        std.mem.sort(FileEntry, entries, {}, struct {
            fn lt(_: void, x: FileEntry, y: FileEntry) bool {
                return @backingInt(x.file) < @backingInt(y.file);
            }
        }.lt);
        const none = try b.compiles.getOrPut(b.gpa, .{ .root = null, .std_root = std_root, .builtin = default_builtin });
        if (!none.found_existing) none.value_ptr.* = &.{};
        const compiles = try a.alloc(Compile, b.compiles.count());
        for (compiles, b.compiles.keys(), b.compiles.values()) |*c, k, modules| c.* = .{ .root = k.root, .std_root = k.std_root, .builtin = k.builtin, .modules = modules, .error_limit = k.error_limit };
        b.files.deinit(b.gpa);
        b.others.deinit(b.gpa);
        b.compiles.deinit(b.gpa);
        return .{ .arena = b.arena.state, .std_root = std_root, .default_builtin = default_builtin, .modules = b.modules.items, .compiles = compiles, .none = @intCast(none.index), .files = entries };
    }
};

pub fn entry(g: *const ModuleGraph, file: FileId) ?FileEntry {
    const i = std.sort.binarySearch(FileEntry, g.files, file, struct {
        fn order(f: FileId, e: FileEntry) std.math.Order {
            return std.math.order(@backingInt(f), @backingInt(e.file));
        }
    }.order) orelse return null;
    return g.files[i];
}

/// The compilation a file is analyzed in when no other compilation reaches it (an index into
/// `compiles`): the one that reached the file first, or `none` for files reached from no compile
/// step; null only for graphs not built by `Builder`
pub fn home(g: *const ModuleGraph, file: FileId) ?u32 {
    const e = g.entry(file) orelse return g.none;
    return e.compile orelse g.none;
}

/// `std`, `builtin` and `root`: the names whose targets depend on the compilation
pub fn isContextName(name: []const u8) bool {
    for ([_][]const u8{ "std", "builtin", "root" }) |n| if (std.mem.eql(u8, name, n)) return true;
    return false;
}

/// Target of `@import(name)` in file `file` (module names: std, builtin, root, and the modules
/// imported by each module the file belongs to; relative paths do not go through the module graph
/// and are not handled here), in the file's own compilation
pub fn importTarget(g: *const ModuleGraph, file: FileId, name: []const u8) ?FileId {
    if (isContextName(name)) return g.contextImport(file, g.home(file), name);
    const e = g.entry(file) orelse return null;
    // For a file in several modules, look the name up in each in turn; when several modules import
    // the same name (possibly pointing to different modules), take the one from the
    // highest-priority module
    if (g.moduleImport(e.module, name)) |m| return g.modules[m].root;
    for (e.others) |other| if (g.moduleImport(other, name)) |m| return g.modules[m].root;
    return null;
}

/// Target of `@import(name)` for `name` in `std`, `builtin` and `root` in file `file` analyzed in
/// compilation `context` (null: no compilation is known; the file then uses the standard library
/// of the zig environment, the builtin of its module or the default one, and no root)
pub fn contextImport(g: *const ModuleGraph, file: FileId, context: ?u32, name: []const u8) ?FileId {
    const c: Compile = if (context) |i| g.compiles[i] else .{ .root = null };
    if (std.mem.eql(u8, name, "std")) return c.std_root orelse g.std_root;
    if (std.mem.eql(u8, name, "root")) return c.root;
    // The standard library uses the builtin of the root module of its compilation (matching the
    // compiler); a module uses its own builtin in that compilation
    const e = g.entry(file) orelse return c.builtin orelse g.default_builtin;
    if (e.module == std_module) return c.builtin orelse g.default_builtin;
    if (context == e.compile) return g.modules[e.module].builtin orelse g.default_builtin;
    for ([_][]const u32{ &.{e.module}, e.others }) |modules| for (modules) |m| {
        for (c.modules) |mb| if (mb.module == m) return mb.builtin orelse g.default_builtin;
    };
    return c.builtin orelse g.default_builtin;
}

/// All targets of `@import(name)` in file `file`: there are several when the modules the file
/// belongs to import different modules as `name`; ordered by module priority without duplicates,
/// the first one being the result of `importTarget` (empty when that is null)
pub fn importTargets(g: *const ModuleGraph, arena: Allocator, file: FileId, name: []const u8) Allocator.Error![]const FileId {
    const first = g.importTarget(file, name) orelse return &.{};
    var targets: std.ArrayList(FileId) = .empty;
    try targets.append(arena, first);
    // std, builtin and root have only one target
    if (isContextName(name)) return targets.items;
    // When `module` imports this name, its target is `first`
    for (g.entry(file).?.others) |other| {
        const target = g.modules[g.moduleImport(other, name) orelse continue].root orelse continue;
        if (std.mem.indexOfScalar(FileId, targets.items, target) == null) try targets.append(arena, target);
    }
    return targets.items;
}

/// The module that module `module` imports as `name`
fn moduleImport(g: *const ModuleGraph, module: u32, name: []const u8) ?u32 {
    if (module == std_module) return null;
    for (g.modules[module].imports) |imp| {
        if (std.mem.eql(u8, imp.name, name)) return imp.module;
    }
    return null;
}

/// Import names of the modules the file belongs to (without duplicates, by module priority)
pub fn importNames(g: *const ModuleGraph, arena: Allocator, file: FileId) Allocator.Error![]const []const u8 {
    const e = g.entry(file) orelse return &.{};
    var names: std.ArrayList([]const u8) = .empty;
    const first = [_]u32{e.module};
    for ([_][]const u32{ &first, e.others }) |modules| for (modules) |m| {
        if (m == std_module) continue;
        for (g.modules[m].imports) |imp| {
            for (names.items) |n| {
                if (std.mem.eql(u8, n, imp.name)) break;
            } else try names.append(arena, imp.name);
        }
    };
    return names.items;
}

pub fn eql(a: *const ModuleGraph, b: *const ModuleGraph) bool {
    return deepEql(a.std_root, b.std_root) and deepEql(a.default_builtin, b.default_builtin) and deepEql(a.modules, b.modules) and deepEql(a.compiles, b.compiles) and a.none == b.none and deepEql(a.files, b.files);
}

/// Query engine input; null when not set (no project and no zig environment information)
pub const Input = struct {
    pub const kind: engine.Kind = .input;
    pub const Key = void;
    pub const Value = ?*const ModuleGraph;
    pub const default: Value = null;

    pub fn eql(a: Value, b: Value) bool {
        if (a == null or b == null) return a == null and b == null;
        return a.?.eql(b.?);
    }

    pub fn deinit(v: *Value, gpa: Allocator) void {
        if (v.*) |g| {
            const m: *ModuleGraph = @constCast(g);
            m.deinit(gpa);
            gpa.destroy(m);
        }
    }
};

/// Targets of the module-name imports in a file (the `@import` strings that appear in the file,
/// plus std, builtin and root).
///
/// Name resolution reads the module graph through this query: other changes to the module graph
/// (such as new files or the import tables of other modules) are cut off here and do not cause the
/// inference that depends on it to be recomputed (the module graph is updated many times while a
/// project loads)
pub const FileImports = struct {
    pub const kind: engine.Kind = .derived;
    pub const Key = FileId;
    pub const Value = *const Table;

    pub const Table = struct {
        /// Arena holding the `Table` itself, `names` and `targets`; only its `State` is kept, for
        /// the same reason as `ModuleGraph.arena`
        arena: std.heap.ArenaAllocator.State,
        names: []const []const u8,
        targets: []const ?FileId,

        /// null when the name is not in the table; `.{ null }` when it is in the table but has
        /// no target
        pub fn get(t: *const Table, name: []const u8) ??FileId {
            for (t.names, t.targets) |n, target| if (std.mem.eql(u8, n, name)) return target;
            return null;
        }
    };

    pub fn compute(ctx: anytype, file: Key) engine.Error!Value {
        const graph = try ctx.get(Input, {});
        const index = try ctx.get(FileIndex.Query, file);
        var arena: std.heap.ArenaAllocator = .init(ctx.db.gpa);
        errdefer arena.deinit();
        const a = arena.allocator();
        var names: std.ArrayList([]const u8) = .empty;
        for ([_][]const u8{ "std", "builtin", "root" }) |n| try names.append(a, n);
        for (index.imports) |n| {
            if (std.mem.endsWith(u8, n, ".zig") or std.mem.endsWith(u8, n, ".zon")) continue;
            for (names.items) |x| {
                if (std.mem.eql(u8, x, n)) break;
            } else try names.append(a, try a.dupe(u8, n));
        }
        const targets = try a.alloc(?FileId, names.items.len);
        for (names.items, targets) |n, *t| t.* = if (graph) |g| g.importTarget(file, n) else null;
        const table = try a.create(Table);
        table.* = .{ .arena = undefined, .names = names.items, .targets = targets };
        table.arena = arena.state;
        return table;
    }

    pub fn eql(a: Value, b: Value) bool {
        return deepEql(a.names, b.names) and deepEql(a.targets, b.targets);
    }

    pub fn deinit(v: *Value, gpa: Allocator) void {
        var arena = v.*.arena.promote(gpa);
        arena.deinit();
    }
};

/// Root file of the standard library of a compilation (an index into `compiles`; null: of the zig
/// environment): like `FileImports`, cuts off other changes to the module graph
pub const StdRoot = struct {
    pub const kind: engine.Kind = .derived;
    pub const Key = ?u32;
    pub const Value = ?FileId;

    pub fn compute(ctx: anytype, context: Key) engine.Error!Value {
        const graph = try ctx.get(Input, {}) orelse return null;
        const c = context orelse return graph.std_root;
        if (c >= graph.compiles.len) return graph.std_root;
        return graph.compiles[c].std_root orelse graph.std_root;
    }
};

/// The compilation a file is analyzed in by itself (`ModuleGraph.home`); like `FileImports`, cuts
/// off other changes to the module graph
pub const FileContext = struct {
    pub const kind: engine.Kind = .derived;
    pub const Key = FileId;
    pub const Value = ?u32;

    pub fn compute(ctx: anytype, file: Key) engine.Error!Value {
        const graph = try ctx.get(Input, {}) orelse return null;
        return graph.home(file);
    }
};

/// Targets of `@import("std")`, `@import("builtin")` and `@import("root")` in a file analyzed in a
/// given compilation (`ModuleGraph.contextImport`), in that order; like `FileImports`, cuts off
/// other changes to the module graph
pub const ContextImports = struct {
    pub const kind: engine.Kind = .derived;
    pub const Key = struct { file: FileId, context: u32 };
    pub const Value = [3]?FileId;

    pub const names = [3][]const u8{ "std", "builtin", "root" };

    pub fn compute(ctx: anytype, key: Key) engine.Error!Value {
        const graph = try ctx.get(Input, {}) orelse return @splat(null);
        if (key.context >= graph.compiles.len) return @splat(null);
        var out: Value = undefined;
        for (names, &out) |n, *t| t.* = graph.contextImport(key.file, key.context, n);
        return out;
    }
};

const testing = std.testing;
const native = @import("../util/test_path.zig").native;

test "a file in several modules resolves imports from each of them" {
    const gpa = testing.allocator;
    var vfs: Vfs = .init(testing.io, gpa);
    defer vfs.deinit();
    // The exe module (0) and the test module (1) share the root file main.zig: in exe, dep → a;
    // in test, dep → b, plus helper → b
    var modules = [_]ProjectModel.Module{
        .{ .root_file = native("/p/src/main.zig"), .imports = &.{.{ .name = "dep", .module = 2 }} },
        .{ .root_file = native("/p/src/main.zig"), .imports = &.{ .{ .name = "dep", .module = 3 }, .{ .name = "helper", .module = 3 } } },
        .{ .root_file = native("/p/a.zig"), .imports = &.{} },
        .{ .root_file = native("/p/b.zig"), .imports = &.{} },
    };
    const steps = [_]ProjectModel.Step{
        .{ .name = "exe", .kind = .{ .compile = .{ .root_module = 0 } }, .deps = &.{} },
        .{ .name = "test", .kind = .{ .compile = .{ .root_module = 1 } }, .deps = &.{} },
    };
    const model: ProjectModel = .{ .arena = .{}, .build_root = native("/p"), .std_root = native("/zig/std/std.zig"), .steps = &steps, .modules = &modules, .default_step = 0 };
    const main = try vfs.intern(native("/p/src/main.zig"));
    const a = try vfs.intern(native("/p/a.zig"));
    const b = try vfs.intern(native("/p/b.zig"));
    // The compile set (the diagnostics step is exe) and the set of all compile steps (exe first)
    var cs: CompileSet.Result = .{};
    defer cs.deinit(gpa);
    try cs.files.put(gpa, main, .{ .module = 0, .step = 0 });
    try cs.files.put(gpa, a, .{ .module = 2, .step = 0 });
    var extra: CompileSet.Result = .{};
    defer extra.deinit(gpa);
    try extra.files.put(gpa, main, .{ .module = 0, .step = 0 });
    try extra.files.put(gpa, a, .{ .module = 2, .step = 0 });
    try extra.files.put(gpa, b, .{ .module = 3, .step = 1 });
    try extra.others.put(gpa, .{ .file = main, .module = 1 }, {});

    var builder: Builder = .init(gpa, &vfs);
    try builder.add(&model, &cs, &extra);
    var g = try builder.finish(null, null);
    defer g.deinit(gpa);
    try testing.expectEqualSlices(u32, &.{1}, g.entry(main).?.others);
    // A name imported only by the test module also resolves
    try testing.expectEqual(@as(?FileId, b), g.importTarget(main, "helper"));
    // A name imported by both modules resolves to the one in the preferred module (exe, in the
    // compile set)
    try testing.expectEqual(@as(?FileId, a), g.importTarget(main, "dep"));
    try testing.expectEqual(null, g.importTarget(main, "other"));
    // `@import("root")` resolves to the root module of the compile step of the preferred membership
    try testing.expectEqual(@as(?FileId, main), g.importTarget(main, "root"));

    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    const names = try g.importNames(arena.allocator(), main);
    try testing.expectEqual(2, names.len);
    try testing.expectEqualStrings("dep", names[0]);
    try testing.expectEqualStrings("helper", names[1]);
}

test "importTargets lists the targets of every module of a file in priority order" {
    const gpa = testing.allocator;
    var vfs: Vfs = .init(testing.io, gpa);
    defer vfs.deinit();
    // The modules of exe (0), test (1) and check (4) share the root file main.zig, with priority in
    // that order
    var modules = [_]ProjectModel.Module{
        .{ .root_file = native("/p/src/main.zig"), .imports = &.{ .{ .name = "dep", .module = 2 }, .{ .name = "same", .module = 2 } } },
        .{ .root_file = native("/p/src/main.zig"), .imports = &.{ .{ .name = "dep", .module = 3 }, .{ .name = "same", .module = 2 }, .{ .name = "helper", .module = 3 }, .{ .name = "opt", .module = 2 } } },
        .{ .root_file = native("/p/a.zig"), .imports = &.{} },
        .{ .root_file = native("/p/b.zig"), .imports = &.{} },
        .{ .root_file = native("/p/src/main.zig"), .imports = &.{ .{ .name = "dep", .module = 2 }, .{ .name = "opt", .module = 3 } } },
    };
    const steps = [_]ProjectModel.Step{
        .{ .name = "exe", .kind = .{ .compile = .{ .root_module = 0 } }, .deps = &.{} },
        .{ .name = "test", .kind = .{ .compile = .{ .root_module = 1 } }, .deps = &.{} },
    };
    const model: ProjectModel = .{ .arena = .{}, .build_root = native("/p"), .std_root = native("/zig/std/std.zig"), .steps = &steps, .modules = &modules, .default_step = 0 };
    const main = try vfs.intern(native("/p/src/main.zig"));
    const a = try vfs.intern(native("/p/a.zig"));
    const b = try vfs.intern(native("/p/b.zig"));
    const std_root = try vfs.intern(native("/zig/std/std.zig"));
    var cs: CompileSet.Result = .{};
    defer cs.deinit(gpa);
    try cs.files.put(gpa, main, .{ .module = 0, .step = 0 });
    try cs.files.put(gpa, a, .{ .module = 2, .step = 0 });
    try cs.files.put(gpa, b, .{ .module = 3, .step = 1 });
    try cs.others.put(gpa, .{ .file = main, .module = 1 }, {});
    try cs.others.put(gpa, .{ .file = main, .module = 4 }, {});

    var builder: Builder = .init(gpa, &vfs);
    try builder.add(&model, &cs, null);
    var g = try builder.finish(std_root, null);
    defer g.deinit(gpa);
    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    const ar = arena.allocator();
    // Different targets are all listed, by module priority; a target in check that is the same as
    // in exe is not repeated
    try testing.expectEqualSlices(FileId, &.{ a, b }, try g.importTargets(ar, main, "dep"));
    // All modules have the same target
    try testing.expectEqualSlices(FileId, &.{a}, try g.importTargets(ar, main, "same"));
    // A name imported by only one module
    try testing.expectEqualSlices(FileId, &.{b}, try g.importTargets(ar, main, "helper"));
    // The highest-priority module does not import this name
    try testing.expectEqualSlices(FileId, &.{ a, b }, try g.importTargets(ar, main, "opt"));
    try testing.expectEqualSlices(FileId, &.{}, try g.importTargets(ar, main, "other"));
    try testing.expectEqualSlices(FileId, &.{std_root}, try g.importTargets(ar, main, "std"));
    try testing.expectEqualSlices(FileId, &.{main}, try g.importTargets(ar, main, "root"));
    // The first target is the result of `importTarget`
    for ([_][]const u8{ "dep", "same", "helper", "opt", "std", "root" }) |name| {
        try testing.expectEqual(g.importTarget(main, name), (try g.importTargets(ar, main, name))[0]);
    }
}

test "a file in many modules keeps its other modules in linear space" {
    // Guards against copying the existing memberships every time one is added: a file in k modules
    // would leave O(k²) garbage in the module graph's arena
    const gpa = testing.allocator;
    var vfs: Vfs = .init(testing.io, gpa);
    defer vfs.deinit();
    const k = 1000;
    var modules: [k]ProjectModel.Module = undefined;
    for (&modules) |*m| m.* = .{ .root_file = native("/p/src/main.zig"), .imports = &.{} };
    const steps = [_]ProjectModel.Step{.{ .name = "exe", .kind = .{ .compile = .{ .root_module = 0 } }, .deps = &.{} }};
    const model: ProjectModel = .{ .arena = .{}, .build_root = native("/p"), .std_root = native("/zig/std/std.zig"), .steps = &steps, .modules = &modules, .default_step = 0 };
    const main = try vfs.intern(native("/p/src/main.zig"));
    var cs: CompileSet.Result = .{};
    defer cs.deinit(gpa);
    try cs.files.put(gpa, main, .{ .module = 0, .step = 0 });
    for (1..k) |m| try cs.others.put(gpa, .{ .file = main, .module = @intCast(m) }, {});

    var builder: Builder = .init(gpa, &vfs);
    try builder.add(&model, &cs, null);
    var g = try builder.finish(null, null);
    defer g.deinit(gpa);
    const others = g.entry(main).?.others;
    try testing.expectEqual(k - 1, others.len);
    for (others, 1..) |m, i| try testing.expectEqual(i, m);
    // These memberships take only 4 KB; copying them one by one would leave about 2 MB of garbage
    try testing.expect(g.arena.promote(gpa).queryCapacity() < 512 * 1024);
}

test "compilations: std, builtin and root of a file depend on the compilation analyzing it" {
    const gpa = testing.allocator;
    var vfs: Vfs = .init(testing.io, gpa);
    defer vfs.deinit();
    // An exe for another target (module 0) and a host generator (module 1) share module 2; a
    // second exe with the same root module and builtin is the same compilation as the first
    var modules = [_]ProjectModel.Module{
        .{ .root_file = native("/p/src/main.zig"), .imports = &.{.{ .name = "common", .module = 2 }} },
        .{ .root_file = native("/p/tools/gen.zig"), .imports = &.{.{ .name = "common", .module = 2 }} },
        .{ .root_file = native("/p/src/common.zig"), .imports = &.{} },
    };
    var builtins = [_]ProjectModel.Builtin{
        .{ .args = &.{}, .file = native("/c/target.zig") },
        .{ .args = &.{}, .file = native("/c/host.zig") },
    };
    const steps = [_]ProjectModel.Step{
        .{ .name = "exe", .kind = .{ .compile = .{ .root_module = 0, .modules = &.{ .{ .module = 0, .builtin = 0 }, .{ .module = 2, .builtin = 0 } } } }, .deps = &.{} },
        .{ .name = "gen", .kind = .{ .compile = .{ .root_module = 1, .modules = &.{ .{ .module = 1, .builtin = 1 }, .{ .module = 2, .builtin = 1 } } } }, .deps = &.{} },
        .{ .name = "exe2", .kind = .{ .compile = .{ .root_module = 0, .modules = &.{ .{ .module = 0, .builtin = 0 }, .{ .module = 2, .builtin = 0 } } } }, .deps = &.{} },
    };
    const model: ProjectModel = .{ .arena = .{}, .build_root = native("/p"), .std_root = native("/zig/std/std.zig"), .steps = &steps, .modules = &modules, .builtins = &builtins, .default_step = 0 };
    const main = try vfs.intern(native("/p/src/main.zig"));
    const extra = try vfs.intern(native("/p/src/extra.zig"));
    const gen = try vfs.intern(native("/p/tools/gen.zig"));
    const common = try vfs.intern(native("/p/src/common.zig"));
    const std_root = try vfs.intern(native("/zig/std/std.zig"));
    const orphan = try vfs.intern(native("/p/tools/orphan.zig"));
    const target_builtin = try vfs.intern(native("/c/target.zig"));
    const host_builtin = try vfs.intern(native("/c/host.zig"));
    const default_builtin = try vfs.intern(native("/c/default.zig"));
    var cs: CompileSet.Result = .{};
    defer cs.deinit(gpa);
    try cs.files.put(gpa, main, .{ .module = 0, .step = 0 });
    try cs.files.put(gpa, common, .{ .module = 2, .step = 0 });
    try cs.files.put(gpa, std_root, .{ .module = std_module, .step = 0 });
    try cs.files.put(gpa, gen, .{ .module = 1, .step = 1 });
    try cs.files.put(gpa, extra, .{ .module = 0, .step = 2 });
    try cs.modules.put(gpa, 0, 0);
    try cs.modules.put(gpa, 1, 1);
    try cs.modules.put(gpa, 2, 0);

    var builder: Builder = .init(gpa, &vfs);
    try builder.add(&model, &cs, null);
    var g = try builder.finish(std_root, default_builtin);
    defer g.deinit(gpa);
    // exe (and exe2), gen, and the compilation of files in no compile step
    try testing.expectEqual(3, g.compiles.len);
    const exe_c: u32 = g.home(main).?;
    const gen_c: u32 = g.home(gen).?;
    try testing.expectEqual(exe_c, g.home(extra).?);
    try testing.expectEqual(exe_c, g.home(std_root).?);
    try testing.expectEqual(g.none.?, g.home(orphan).?);
    try testing.expect(exe_c != gen_c and gen_c != g.none.?);
    // The standard library takes the builtin and root of the compilation analyzing it
    try testing.expectEqual(target_builtin, g.contextImport(std_root, exe_c, "builtin").?);
    try testing.expectEqual(host_builtin, g.contextImport(std_root, gen_c, "builtin").?);
    try testing.expectEqual(default_builtin, g.contextImport(std_root, g.none, "builtin").?);
    try testing.expectEqual(main, g.contextImport(std_root, exe_c, "root").?);
    try testing.expectEqual(gen, g.contextImport(std_root, gen_c, "root").?);
    try testing.expectEqual(null, g.contextImport(std_root, g.none, "root"));
    // A module shared by both takes its builtin in each of them
    try testing.expectEqual(target_builtin, g.contextImport(common, exe_c, "builtin").?);
    try testing.expectEqual(host_builtin, g.contextImport(common, gen_c, "builtin").?);
    // Files in no compile step use the default builtin and have no root
    try testing.expectEqual(default_builtin, g.importTarget(orphan, "builtin").?);
    try testing.expectEqual(null, g.importTarget(orphan, "root"));
    try testing.expectEqual(std_root, g.importTarget(orphan, "std").?);
}
